SourceCode.Declaration:
internal class GUPPricingRuleBuilder_RuleLine extends GUPPricingRuleBuilder
{
    private GUPRuleTable ruleTable;

}

Method.Source:
    public static void main(Args args)
    {
        GUPPricingRuleBuilder_RuleLine createRule;
        createRule = new GUPPricingRuleBuilder_RuleLine(args.record());

        createRule.createRecord();
    }

    public void initMasterRecord()
    {
        GUPRuleLine ruleLine;

        ruleLine.clear();
        ruleLine.RuleId = this.ruleTable.RuleId;
        ruleLine.LineNum = GUPRuleLine::lastLineNum(ruleLine.RuleId) + SystemParameters::getSystemLineNumberIncrement();

        this.masterRecord = ruleLine;
    }

    public void linkPricingRule(GUPPricingRule _pricingRule)
    {
        if (this.dialogOk && _pricingRule)
        {
            GUPRuleLine createdRuleLine = masterRecord;

            createdRuleLine.LinePricingRule = _pricingRule.RecId;
        }
    }
